#include <zephyr/pm/device.h>
#include <zephyr/pm/device_runtime.h>
#include <zephyr/pm/policy.h>
#include <zephyr/device.h>
#include <zephyr/init.h>
#include <zephyr/kernel.h>
#include <zephyr/logging/log.h>
#include <zephyr/sys/__assert.h>
#include <zephyr/sys/atomic.h>
#include <zephyr/sys/util.h>

LOG_MODULE_REGISTER(pm_device, CONFIG_PM_DEVICE_LOG_LEVEL);

#ifdef CONFIG_PM_DEVICE_RUNTIME
static K_MUTEX_DEFINE(pm_device_mutex);
#endif

static const struct device *pm_device_list[Z_DEVICE_PM_DEVICE_COUNT];
static size_t pm_device_count;

#ifdef CONFIG_PM_DEVICE_RUNTIME
static void pm_device_runtime_work_handler(struct k_work *work);
static enum pm_device_state pm_device_runtime_get(const struct device *dev);
static bool pm_device_runtime_is_busy(const struct device *dev);
static int pm_device_runtime_set(const struct device *dev, enum pm_device_state state);
#endif

static int pm_device_state_set_internal(const struct device *dev,
					enum pm_device_state state)
{
	struct pm_device *pm = dev->pm;

	if (pm == NULL) {
		return -ENOTSUP;
	}

	if (pm->state == state) {
		return 0;
	}

	int ret = dev->pm_control(dev, state);
	if (ret == 0) {
		pm->state = state;
	} else {
		LOG_ERR("Device %s failed to set state %d (err %d)",
			dev->name, state, ret);
	}

	return ret;
}

int pm_device_action(const struct device *dev, enum pm_device_state state)
{
	__ASSERT_NO_MSG(dev != NULL);

	if (dev->pm == NULL) {
		return -ENOTSUP;
	}

#ifdef CONFIG_PM_DEVICE_RUNTIME
	if (pm_device_runtime_is_enabled(dev)) {
		return pm_device_runtime_set(dev, state);
	}
#endif

	return pm_device_state_set_internal(dev, state);
}

enum pm_device_state pm_device_state_get(const struct device *dev)
{
	__ASSERT_NO_MSG(dev != NULL);

	if (dev->pm == NULL) {
		return PM_DEVICE_STATE_ACTIVE;
	}

#ifdef CONFIG_PM_DEVICE_RUNTIME
	if (pm_device_runtime_is_enabled(dev)) {
		return pm_device_runtime_get(dev);
	}
#endif

	return dev->pm->state;
}

bool pm_device_is_busy(const struct device *dev)
{
	__ASSERT_NO_MSG(dev != NULL);

	if (dev->pm == NULL) {
		return false;
	}

#ifdef CONFIG_PM_DEVICE_RUNTIME
	if (pm_device_runtime_is_enabled(dev)) {
		return pm_device_runtime_is_busy(dev);
	}
#endif

	return dev->pm->ref_count > 0;
}

#ifdef CONFIG_PM_DEVICE_SUSPEND_STATS
void pm_device_stats_show(const struct device *dev)
{
	struct pm_device *pm = dev->pm;

	if (pm == NULL) {
		return;
	}

	LOG_INF("Device %s: total_suspend_cycles=%llu, total_resume_cycles=%llu",
		dev->name, pm->total_suspend_cycles, pm->total_resume_cycles);
}
#endif /* CONFIG_PM_DEVICE_SUSPEND_STATS */

static int pm_device_init(const struct device *dev)
{
	struct pm_device *pm = dev->pm;

	if (pm == NULL) {
		return 0;
	}

	pm->state = PM_DEVICE_STATE_ACTIVE;
	pm->ref_count = 0;

#ifdef CONFIG_PM_DEVICE_RUNTIME
	pm->runtime_state = PM_DEVICE_RUNTIME_STATE_ACTIVE;
	pm->usage_count = 0;
	k_work_init_delayable(&pm->work, pm_device_runtime_work_handler);
	pm->dev = dev; /* Store back-pointer for runtime PM work */
#endif

	return 0;
}

/*
 * This function is called during system initialization for each device
 * that has PM capabilities.
 */
static int pm_device_sys_init(void)
{
	const struct device *dev;
	size_t i = 0;

	Z_FOR_EACH_DEVICE_PM(dev) {
		pm_device_init(dev);
		pm_device_list[i++] = dev;
	}
	pm_device_count = i;

	return 0;
}

SYS_INIT(pm_device_sys_init, PRE_KERNEL_2, CONFIG_KERNEL_INIT_PRIORITY_DEFAULT);

/*
 * Suspend all devices in reverse order of initialization.
 * This ensures that dependencies are suspended correctly.
 */
int pm_device_suspend_all(void)
{
	int ret = 0;
	int overall_ret = 0;

	for (int i = pm_device_count - 1; i >= 0; i--) {
		const struct device *dev = pm_device_list[i];

		if (pm_device_is_busy(dev)) {
			LOG_DBG("Device %s is busy, cannot suspend", dev->name);
			overall_ret = -EBUSY; /* Mark overall failure, but continue */
			continue;
		}

		if (pm_device_state_get(dev) == PM_DEVICE_STATE_SUSPENDED) {
			continue;
		}

		ret = pm_device_action(dev, PM_DEVICE_STATE_SUSPENDED);
		if (ret < 0) {
			LOG_ERR("Failed to suspend device %s (err %d)", dev->name, ret);
			overall_ret = ret; /* Mark overall failure, but continue */
		}
	}

	return overall_ret;
}

/*
 * Resume all devices in order of initialization.
 * This ensures that dependencies are resumed correctly.
 */
int pm_device_resume_all(void)
{
	int ret = 0;
	int overall_ret = 0;

	for (size_t i = 0; i < pm_device_count; i++) {
		const struct device *dev = pm_device_list[i];

		if (pm_device_state_get(dev) == PM_DEVICE_STATE_ACTIVE) {
			continue;
		}

		ret = pm_device_action(dev, PM_DEVICE_STATE_ACTIVE);
		if (ret < 0) {
			LOG_ERR("Failed to resume device %s (err %d)", dev->name, ret);
			overall_ret = ret; /* Mark overall failure, but continue */
		}
	}

	return overall_ret;
}

#ifdef CONFIG_PM_DEVICE_RUNTIME
int pm_device_runtime_get(const struct device *dev)
{
	__ASSERT_NO_MSG(dev != NULL);
	__ASSERT_NO_MSG(dev->pm != NULL);

	k_mutex_lock(&pm_device_mutex, K_FOREVER);

	if (dev->pm->runtime_state == PM_DEVICE_RUNTIME_STATE_SUSPENDING) {
		k_mutex_unlock(&pm_device_mutex);
		return -EAGAIN;
	}

	if (dev->pm->usage_count == 0) {
		/* If device is suspended, resume it */
		if (dev->pm->runtime_state == PM_DEVICE_RUNTIME_STATE_SUSPENDED) {
			int ret = pm_device_state_set_internal(dev, PM_DEVICE_STATE_ACTIVE);
			if (ret < 0) {
				k_mutex_unlock(&pm_device_mutex);
				return ret;
			}
			dev->pm->runtime_state = PM_DEVICE_RUNTIME_STATE_ACTIVE;
		}
	}
	dev->pm->usage_count++;

	k_mutex_unlock(&pm_device_mutex);
	return 0;
}

int pm_device_runtime_put(const struct device *dev)
{
	__ASSERT_NO_MSG(dev != NULL);
	__ASSERT_NO_MSG(dev->pm != NULL);

	k_mutex_lock(&pm_device_mutex, K_FOREVER);

	if (dev->pm->usage_count == 0) {
		k_mutex_unlock(&pm_device_mutex);
		return -EFAULT; /* Should not happen */
	}

	dev->pm->usage_count--;
	if (dev->pm->usage_count == 0) {
		/* Schedule suspend if no longer in use */
		k_work_reschedule(&dev->pm->work, K_MSEC(CONFIG_PM_DEVICE_RUNTIME_DELAY));
	}

	k_mutex_unlock(&pm_device_mutex);
	return 0;
}

bool pm_device_runtime_is_enabled(const struct device *dev)
{
	__ASSERT_NO_MSG(dev != NULL);
	__ASSERT_NO_MSG(dev->pm != NULL);

	return atomic_test_bit(&dev->pm->flags, PM_DEVICE_FLAG_RUNTIME_ENABLED);
}

int pm_device_runtime_enable(const struct device *dev)
{
	__ASSERT_NO_MSG(dev != NULL);
	__ASSERT_NO_MSG(dev->pm != NULL);

	atomic_set_bit(&dev->pm->flags, PM_DEVICE_FLAG_RUNTIME_ENABLED);
	return 0;
}

int pm_device_runtime_disable(const struct device *dev)
{
	__ASSERT_NO_MSG(dev != NULL);
	__ASSERT_NO_MSG(dev->pm != NULL);

	k_mutex_lock(&pm_device_mutex, K_FOREVER);

	/* Cancel any pending suspend work */
	k_work_cancel_delayable(&dev->pm->work);

	/* If device is suspended, resume it */
	if (dev->pm->runtime_state == PM_DEVICE_RUNTIME_STATE_SUSPENDED) {
		int ret = pm_device_state_set_internal(dev, PM_DEVICE_STATE_ACTIVE);
		if (ret < 0) {
			k_mutex_unlock(&pm_device_mutex);
			return ret;
		}
		dev->pm->runtime_state = PM_DEVICE_RUNTIME_STATE_ACTIVE;
	}

	atomic_clear_bit(&dev->pm->flags, PM_DEVICE_FLAG_RUNTIME_ENABLED);
	dev->pm->usage_count = 0; /* Reset usage count */

	k_mutex_unlock(&pm_device_mutex);
	return 0;
}

static void pm_device_runtime_work_handler(struct k_work *work)
{
	struct k_work_delayable *dwork = k_work_delayable_from_work(work);
	struct pm_device *pm = CONTAINER_OF(dwork, struct pm_device, work);
	const struct device *dev = pm->dev;

	k_mutex_lock(&pm_device_mutex, K_FOREVER);

	if (pm->usage_count > 0) {
		/* Device became busy again, cancel suspend */
		k_mutex_unlock(&pm_device_mutex);
		return;
	}

	if (pm->runtime_state == PM_DEVICE_RUNTIME_STATE_ACTIVE) {
		pm->runtime_state = PM_DEVICE_RUNTIME_STATE_SUSPENDING;
		k_mutex_unlock(&pm_device_mutex);

		int ret = pm_device_state_set_internal(dev, PM_DEVICE_STATE_SUSPENDED);

		k_mutex_lock(&pm_device_mutex, K_FOREVER);
		if (ret == 0) {
			pm->runtime_state = PM_DEVICE_RUNTIME_STATE_SUSPENDED;
		} else {
			/* Failed to suspend, revert to active */
			pm->runtime_state = PM_DEVICE_RUNTIME_STATE_ACTIVE;
			LOG_ERR("Runtime suspend failed for %s (err %d)", dev->name, ret);
		}
	}

	k_mutex_unlock(&pm_device_mutex);
}

enum pm_device_state pm_device_runtime_get(const struct device *dev)
{
	__ASSERT_NO_MSG(dev != NULL);
	__ASSERT_NO_MSG(dev->pm != NULL);

	k_mutex_lock(&pm_device_mutex, K_FOREVER);
	enum pm_device_state state;

	if (dev->pm->runtime_state == PM_DEVICE_RUNTIME_STATE_SUSPENDED) {
		state = PM_DEVICE_STATE_SUSPENDED;
	} else {
		state = PM_DEVICE_STATE_ACTIVE;
	}
	k_mutex_unlock(&pm_device_mutex);
	return state;
}

bool pm_device_runtime_is_busy(const struct device *dev)
{
	__ASSERT_NO_MSG(dev != NULL);
	__ASSERT_NO_MSG(dev->pm != NULL);

	k_mutex_lock(&pm_device_mutex, K_FOREVER);
	bool busy = (dev->pm->usage_count > 0 ||
		     dev->pm->runtime_state == PM_DEVICE_RUNTIME_STATE_SUSPENDING);
	k_mutex_unlock(&pm_device_mutex);
	return busy;
}

int pm_device_runtime_set(const struct device *dev, enum pm_device_state state)
{
	__ASSERT_NO_MSG(dev != NULL);
	__ASSERT_NO_MSG(dev->pm != NULL);

	int ret = 0;

	k_mutex_lock(&pm_device_mutex, K_FOREVER);

	if (state == PM_DEVICE_STATE_ACTIVE) {
		if (dev->pm->runtime_state == PM_DEVICE_RUNTIME_STATE_SUSPENDED) {
			ret = pm_device_state_set_internal(dev, PM_DEVICE_STATE_ACTIVE);
			if (ret == 0) {
				dev->pm->runtime_state = PM_DEVICE_RUNTIME_STATE_ACTIVE;
			}
		}
		/* Cancel any pending suspend work */
		k_work_cancel_delayable(&dev->pm->work);
	} else if (state == PM_DEVICE_STATE_SUSPENDED) {
		if (dev->pm->usage_count > 0) {
			ret = -EBUSY; /* Cannot suspend if in use */
		} else if (dev->pm->runtime_state == PM_DEVICE_RUNTIME_STATE_ACTIVE) {
			dev->pm->runtime_state = PM_DEVICE_RUNTIME_STATE_SUSPENDING;
			k_mutex_unlock(&pm_device_mutex); /* Unlock before calling driver */

			ret = pm_device_state_set_internal(dev, PM_DEVICE_STATE_SUSPENDED);

			k_mutex_lock(&pm_device_mutex, K_FOREVER); /* Relock */
			if (ret == 0) {
				dev->pm->runtime_state = PM_DEVICE_RUNTIME_STATE_SUSPENDED;
			} else {
				dev->pm->runtime_state = PM_DEVICE_RUNTIME_STATE_ACTIVE;
			}
		}
	} else {
		ret = -EINVAL;
	}

	k_mutex_unlock(&pm_device_mutex);
	return ret;
}

#endif /* CONFIG_PM_DEVICE_RUNTIME */
